async (cursor, num, params) => {
  if (location.hostname !== 'www.photopea.com') throw new Error('[photopea-cutout] 这张标签没连上 photopea.com（现在是 ' + location.href.slice(0, 60) + '，多半是连接被掐断）：去那张标签按一次刷新，别关它');
  if (window._cf_chl_opt || /请稍候|Just a moment|安全验证/.test(document.title + ' ' + (document.body ? document.body.innerText.slice(0, 200) : ''))) throw new Error('[photopea-cutout] Photopea 标签停在 Cloudflare 真人验证页：去那张「Photopea API」标签点一下验证（只需一次，标签常驻不关），再跑');
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const image = String(params.image || '');
  if (!image.startsWith('data:image/')) throw new Error('[photopea-cutout] image 要是 data:image/... 的 data URL');
  const tolerance = Math.max(0, Math.min(255, Number(params.tolerance || 24)));
  const seeds = String(params.seed || '4,4').split(';').map(s => s.split(',').map(Number)).filter(p => p.length === 2 && p.every(Number.isFinite));
  if (!seeds.length) throw new Error('[photopea-cutout] seed 要写成 "x,y"（多个用分号隔开）');
  const contiguous = String(params.contiguous || 'true') !== 'false';
  let keep = []; if (params.keep) { try { keep = JSON.parse(params.keep); } catch (e) { throw new Error('[photopea-cutout] keep 不是合法 JSON: ' + e.message); } if (!Array.isArray(keep) || !keep.every(p => Array.isArray(p) && p.length >= 3)) throw new Error('[photopea-cutout] keep 要是 [[[x,y],...],...]（每个多边形至少 3 点）'); }
  const format = String(params.format || 'png');
  // —— Photopea 宿主：同源 iframe（photopea.com 顶层不听 postMessage，嵌成 iframe 才听）——
  const ensureFrame = async () => {
    let f = document.getElementById('pp');
    if (f) { // 上一轮留下的热 iframe：应一声就复用，不应就换新的
      const alive = await new Promise(res => { const h = e => { if (e.source === f.contentWindow && e.data === 'pong') { window.removeEventListener('message', h); res(true); } }; window.addEventListener('message', h); setTimeout(() => { window.removeEventListener('message', h); res(false); }, 4000); f.contentWindow.postMessage('app.echoToOE("pong");', '*'); });
      if (alive) return f;
      f.remove();
    }
    f = document.createElement('iframe'); f.id = 'pp'; f.style.cssText = 'position:fixed;left:0;top:0;width:100vw;height:100vh;border:0;background:#fff;z-index:2147483647';
    const ready = new Promise((res, rej) => { const h = e => { if (e.source === f.contentWindow && e.data === 'done') { window.removeEventListener('message', h); res(); } }; window.addEventListener('message', h); setTimeout(() => { window.removeEventListener('message', h); rej(new Error('[photopea-cutout] Photopea iframe 25s 没就绪')); }, 25000); });
    f.src = 'https://www.photopea.com/#' + encodeURIComponent(JSON.stringify({ environment: {} }));
    document.body.appendChild(f);
    await ready;
    return f;
  };
  const f = await ensureFrame();
  // 跑一段 Photopea 脚本，等它最后一句 echo 的标记；二进制（saveToOE）顺手收下
  const pp = (script, ms) => new Promise((res, rej) => {
    const mark = 'ok#' + Math.random().toString(36).slice(2, 8); let bin = null; const got = [];
    const h = e => { if (e.source !== f.contentWindow) return; if (e.data instanceof ArrayBuffer) { bin = e.data; return; } if (typeof e.data !== 'string') return; got.push(e.data); if (e.data === mark) { window.removeEventListener('message', h); clearTimeout(t); res({ bin, got }); } };
    const t = setTimeout(() => { window.removeEventListener('message', h); rej(new Error('[photopea-cutout] Photopea 脚本 ' + ms + 'ms 内没跑完（脚本出错时 Photopea 不报错、只是没有回音）: ' + script.slice(0, 120) + ' | 收到: ' + got.join('/'))); }, ms);
    window.addEventListener('message', h);
    f.contentWindow.postMessage(script + '\napp.echoToOE(' + JSON.stringify(mark) + ');', '*');
  });
  let B = 0; // 清完临时文档后已有的文档数（用户自己开着的）；本轮的文档从 app.documents[B] 起
  const probe = async () => (await pp('app.echoToOE("docs=" + app.documents.length);', 5000)).got.find(s => s.startsWith('docs='));
  const waitDocs = async (n, ms) => { const t0 = Date.now(); for (;;) { const s = await probe(); if (s === 'docs=' + (B + n)) return; if (Date.now() - t0 > ms) throw new Error('[photopea-cutout] 等文档就绪超时，现在 ' + s + '，要 docs=' + n); await sleep(300); } };
  await pp('for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();', 8000, '清掉上轮残留的临时文档');
  B = Number(((await probe()) || 'docs=0').slice(5).split(' ')[0]) || 0;
  await waitDocs(0, 8000);
  await pp('app.open(' + JSON.stringify(image) + ');', 20000);
  await waitDocs(1, 20000);
  await pp('app.activeDocument.name = "~stream~cutout";', 5000);
  // 魔棒 = Photoshop 动作描述符 setd（Photopea 的 executeAction 认它；AddT 不认，所以多个种子各自 setd 后靠 keep 多边形收口，不做并集）
  const wand = (x, y) => 'var c = charIDToTypeID; var desc = new ActionDescriptor(); var ref = new ActionReference(); ref.putProperty(c("Chnl"), c("fsel")); desc.putReference(c("null"), ref); var pt = new ActionDescriptor(); pt.putUnitDouble(c("Hrzn"), c("#Pxl"), ' + x + '); pt.putUnitDouble(c("Vrtc"), c("#Pxl"), ' + y + '); desc.putObject(c("T   "), c("Pnt "), pt); desc.putInteger(c("Tlrn"), ' + tolerance + '); desc.putBoolean(c("AntA"), true); desc.putBoolean(c("Cntg"), ' + contiguous + '); executeAction(c("setd"), desc, DialogModes.NO);';
  const bounds = 'var b = d.selection.bounds; app.echoToOE("sel=" + [b[0].value, b[1].value, b[2].value, b[3].value].join(","));';
  const sels = [];
  for (const [x, y] of seeds) {
    let script = 'var d = app.activeDocument; ' + wand(x, y) + ' ' + bounds;
    for (const poly of keep) script += ' d.selection.select(' + JSON.stringify(poly) + ', SelectionType.DIMINISH);';
    script += ' d.selection.clear(); d.selection.deselect();';
    const r = await pp(script, 15000);
    sels.push((r.got.find(s => s.startsWith('sel=')) || 'sel=?').slice(4));
  }
  const { bin, got } = await pp('var d = app.activeDocument; var L = d.layers[0]; app.echoToOE("layer=" + [L.bounds[0].value, L.bounds[1].value, L.bounds[2].value, L.bounds[3].value].join(",")); app.echoToOE("size=" + d.width + "x" + d.height); d.saveToOE(' + JSON.stringify(format) + ');', 20000);
  if (!bin) throw new Error('[photopea-cutout] saveToOE 没回二进制: ' + got.join('/'));

  const keepName = String(params.keep || '');
  if (keepName) await pp('app.activeDocument.name = ' + JSON.stringify(keepName) + '; var kd = app.activeDocument; ' + 'for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();' + ' app.activeDocument = kd;', 8000, '留下结果');
  else await pp('for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();', 8000, '收尾');
  const u8 = new Uint8Array(bin); let s = ''; for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000));
  const pick = k => (got.find(x => x.startsWith(k + '=')) || '').slice(k.length + 1);
  return { items: [{ guid: 'cutout-' + Date.now(), format, size: pick('size'), bounds: pick('layer'), selections: sels.join(';'), bytes: String(u8.length), data: btoa(s) }], cursor: '' };
}
